      spyOn(
        mockCheckoutPaymentService,
        'getPaymentDetailsState'
      ).and.returnValue(
        of({ loading: false, error: false, data: mockPaymentDetails })
      );

      component.ngOnInit();
      fixture.detectChanges();

      expect(
